  const done=['n2','n3','n4'].filter(n=>res.log.some(l=>l.startsWith(n+'.r')));
  res.done=done;
  if(done.length==3)break;
}
const out={};
for(const n of ['n2','n3','n4']) out[n]=await read(n+'.r1');
